import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import api from "../services/api";
import TweetList from "../components/walls/tweetList"; // Adjust path
import { API_ENDPOINTS } from "../services/apiEndpoints";
import Footer from "../components/footer.js";

const WallTweets = () => {
    const { wallId } = useParams();
    const navigate = useNavigate();
    const [tweets, setTweets] = useState(null);
    const [wall, setWall] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const logoUrl = "/path-to-logo.png"; // Same logo as dashboard

    useEffect(() => {
        const fetchWalls = async () => {
            try {
                const res = await api.get(
                    API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId)
                );
                setTweets(res.data);
                const response = await api.get(API_ENDPOINTS.GET_WALL_BY_ID(wallId))
                setWall(response.data);
                setLoading(false);
            } catch (err) {
                setError("Failed to load wall");
                setLoading(false);
            }
        };

        fetchWalls();
    }, []);

    const handleDeleteWall = async () => {
        if (window.confirm("Are you sure you want to delete this wall?")) {
            try {
                await api.delete(API_ENDPOINTS.DELETE_WALL(wallId)); // Adjust endpoint
                navigate("/dashboard");
            } catch (err) {
                setError("Failed to delete wall");
            }
        }
    };

    if (loading) return <div>Loading...</div>;
    if (error) return <div>{error}</div>;
    if (!tweets) return <div>Wall not found</div>;

    return (
        <div className="p-6">
            {/* Header similar to Dashboard */}
            <div className="flex justify-between items-center mb-6">
                <div className="flex items-center">
                    <img
                        src={logoUrl}
                        alt="Logo"
                        className="w-10 h-10 mr-2 rounded-full"
                    />
                    <h2 className="text-2xl font-bold">Abhi's Wall</h2>
                </div>
                <div className="space-x-4">
                    <button
                        onClick={() =>
                            navigate(`/walls/${wallId}/create-tweet`)
                        }
                        className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
                    >
                        Create Tweet
                    </button>
                    <button
                        onClick={handleDeleteWall}
                        className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600"
                    >
                        Delete
                    </button>
                </div>
            </div>
            {tweets && tweets.length > 0 ? (
                <TweetList wallId={wallId} tweets={tweets} />
            ) : (
                "No tweets are added yet."
            )}
            <Footer socialLinks={wall?.socialLinks}/>
        </div>
    );
};

export default WallTweets;
